'use strict';function setup(c,s){s.phase='MAIN_PHASE';s.turnNumber=3;s.activePlayerId='P1';s.pendingEffect=null;for(const p of s.playerOrder){for(const z of ['hand','deck','field','food','territory','discard'])s.player(p)[z]=[];const x=new c.CardInstance({instanceId:s.nextInstanceId(),cardId:'namitentou',ownerId:p,controllerId:p,zone:'TERRITORY',faceDown:true});s.player(p).territory.push(x);}}module.exports={setup};
